def P(slug, category, name, unit, price, image, short, seo_title, seo_desc, intro, specs, uses, faqs):
    return dict(slug=slug, category=category, name=name, unit=unit, price=price, image=image, description=short,
                seoTitle=seo_title, seoDescription=seo_desc, intro=intro,
                specs=[{"label": l, "value": v} for l, v in specs], uses=uses,
                faqs=[{"q": q, "a": a} for q, a in faqs])

